-- Pending seed: apply AFTER 20261104_concept_lessons.sql
-- Original draft lessons, awaiting faculty review; deliberately NOT public via RLS.
with imported(slug,title,explanation,worked_example,question,options,correct_option,feedback) as (values
('observacion','Observar antes de explicar','Una observación registra lo que puede percibirse o medirse; una inferencia propone por qué ocurre.','En una pared se ve una grieta de 2 mm. Eso es una observación; atribuirla al asentamiento del suelo es una hipótesis.','¿Cuál enunciado es una observación?','["La grieta mide aproximadamente 2 mm.","El terreno se hundió.","La obra fue mal diseñada.","La pared fallará mañana."]'::jsonb,0,'La medida describe algo registrable; las otras opciones interpretan causas o anticipan resultados.'),
('medicion','Medir con unidades y contexto','Una medición debe indicar magnitud, unidad, procedimiento y, cuando sea relevante, incertidumbre.','Registrar 2.40 m de altura es más útil que escribir simplemente «2.40».','¿Cuál registro es más completo?','["Temperatura: 32 °C, sensor calibrado.","Temperatura: alta.","Temperatura: 32.","Hace calor."]'::jsonb,0,'La magnitud, unidad e instrumento permiten interpretar y repetir la medición.'),
('evidencia','Hipótesis y pruebas','Una afirmación necesita observaciones pertinentes y un método que reduzca explicaciones alternativas.','Para evaluar un material se prueban muestras comparables bajo condiciones controladas.','¿Qué fortalece una conclusión experimental?','["Comparar condiciones y repetir mediciones.","Confiar en una sola anécdota.","Elegir solo resultados favorables.","Evitar registrar condiciones."]'::jsonb,0,'La comparación y la repetición ayudan a identificar variación y causas alternativas.'),
('sistemas','Entender sistemas conectados','En un sistema, modificar una parte puede afectar otras mediante dependencias y retroalimentación.','En el suministro de agua, demanda, bombeo, energía y almacenamiento se influyen mutuamente.','¿Qué caracteriza al pensamiento sistémico?','["Analizar relaciones y efectos indirectos.","Estudiar solo un componente aislado.","Ignorar cambios de contexto.","Suponer que todo efecto es inmediato."]'::jsonb,0,'La atención a las interacciones permite evaluar consecuencias no evidentes.'),
('etica','Decisiones con consecuencias','La ética ayuda a examinar beneficios, daños, derechos, consentimiento y responsabilidades.','Un tutor con IA debe proteger los datos del estudiante y permitir supervisión humana.','¿Qué práctica protege mejor a un estudiante?','["Recolectar lo mínimo necesario y explicar su uso.","Vender su historial académico.","Ocultar cómo se usa su información.","Compartir contraseñas de acceso."]'::jsonb,0,'La minimización de datos y la transparencia reducen riesgos innecesarios.'),
('matematicas','Relaciones y cantidades','Las matemáticas usan símbolos, números y estructuras para representar problemas con precisión.','Si una pieza cuesta 40 pesos, cuatro piezas cuestan 160 pesos antes de descuentos o fletes.','¿Cuánto cuestan 3 piezas de 40 pesos cada una?','["120 pesos.","43 pesos.","160 pesos.","12 pesos."]'::jsonb,0,'Tres veces cuarenta es 120; el cálculo supone precio constante.'),
('logica','Construir argumentos válidos','La lógica distingue entre la estructura de un razonamiento y la veracidad de sus premisas.','Si un sensor está desconectado, no transmite lecturas; se observa desconexión y se investiga el dato faltante.','¿Cuál ejemplo aplica una regla condicional?','["Si A implica B y ocurre A, entonces B.","A implica B y ocurre B, por tanto A.","Una conclusión se acepta por popularidad.","Una observación elimina toda duda."]'::jsonb,0,'Es una aplicación de modus ponens, siempre que la premisa condicional sea válida.'),
('materia','Materia, cambios y energía','La materia tiene propiedades medibles; la energía interviene en cambios físicos, químicos y térmicos.','Un material puede expandirse al calentarse; su uso requiere considerar condiciones de temperatura.','¿Qué propiedad puede cambiar con temperatura?','["Longitud de una barra por expansión térmica.","La identidad de su fabricante.","Su número de inventario.","El nombre comercial de la pieza."]'::jsonb,0,'La expansión térmica modifica dimensiones en numerosos materiales.'),
('vida','Niveles de organización biológica','Los seres vivos se organizan desde estructuras celulares hasta organismos y ecosistemas.','Las células forman tejidos y estos participan en la función de órganos.','¿Cuál estructura constituye la unidad básica de la vida?','["Célula.","Planeta.","Edificio.","Circuito mecánico."]'::jsonb,0,'La célula es la unidad estructural y funcional básica de los seres vivos.'),
('necesidades','Problemas humanos antes que soluciones','Una necesidad debe comprenderse en su contexto antes de proponer un producto o servicio.','Antes de diseñar una aplicación educativa se observa cómo aprenden y qué barreras encuentran sus usuarios.','¿Qué conviene hacer antes de diseñar una solución?','["Investigar necesidades y restricciones reales.","Elegir la tecnología más vistosa.","Suponer que todos usan lo mismo.","Ignorar diversidad de usuarios."]'::jsonb,0,'El contexto de uso evita resolver problemas equivocados.'),
('datos','De observaciones a datos utilizables','Los datos adquieren sentido cuando conocemos sus variables, unidades, origen, calidad y limitaciones.','Un registro de lluvia sin fecha ni ubicación impide comparar regiones o temporadas.','¿Cuál dato es más interpretable?','["12 mm de lluvia, estación X, 3 de junio.","12 sin unidad.","Un número sin procedencia.","Mucha lluvia."]'::jsonb,0,'Unidad, fecha y procedencia permiten contextualizar el valor.'),
('funciones','Cómo cambian dos variables','Una función relaciona entradas con salidas de manera definida dentro de un dominio.','La distancia recorrida a velocidad constante puede expresarse como distancia = velocidad × tiempo.','A 5 km/h durante 2 h, la distancia idealizada es…','["10 km.","2.5 km.","7 km.","25 km."]'::jsonb,0,'Distancia = 5 × 2 = 10 km, suponiendo velocidad constante.'),
('probabilidad','Razonar bajo incertidumbre','La probabilidad cuantifica qué tan plausible es un resultado según supuestos y evidencia.','Una predicción de lluvia del 70 % no equivale a certeza de que lloverá.','¿Qué significa una probabilidad de 70 %?','["Hay incertidumbre: el evento no es seguro.","El evento ocurrirá sin falta.","Es imposible que no ocurra.","Todos los lugares tendrán igual resultado."]'::jsonb,0,'Una probabilidad menor que 100 % admite que el evento no suceda.'),
('estadistica','Variación, muestras e inferencias','La estadística permite resumir datos y estimar patrones sin perder de vista incertidumbre y sesgos.','Medir rendimientos de una sola obra no basta para estimar el desempeño de todas las regiones.','¿Cuál riesgo aparece con una muestra poco representativa?','["Conclusiones sesgadas sobre la población.","Precisión garantizada.","Desaparición de variación.","Ausencia de incertidumbre."]'::jsonb,0,'La selección de casos afecta qué tan generalizables son los resultados.'),
('algoritmos','Resolver problemas paso a paso','Un algoritmo especifica una secuencia finita de operaciones y condiciones que puede comprobarse.','Clasificar mediciones: verificar unidad, descartar faltantes documentados, agrupar y calcular promedios.','¿Qué mejora un algoritmo?','["Instrucciones claras y reproducibles.","Pasos ambiguos.","Cambios no registrados.","Resultados imposibles de verificar."]'::jsonb,0,'La reproducibilidad permite comprobar y corregir el proceso.'),
('programacion','Convertir algoritmos en programas','Programar consiste en expresar instrucciones para una computadora y comprobar su comportamiento.','Una función calcula costo total usando cantidad y precio, con pruebas para entradas válidas y erróneas.','¿Cuál práctica ayuda a detectar errores?','["Probar casos normales y límites.","Omitir toda validación.","Suponer que siempre funcionará.","No registrar resultados."]'::jsonb,0,'Las pruebas ayudan a identificar comportamientos inesperados.'),
('sensores','De fenómenos a señales','Un sensor transforma una propiedad del entorno en una señal; calibración y frecuencia de muestreo importan.','Un sensor de humedad del suelo puede dar lecturas engañosas si se instala o calibra mal.','¿Qué debe verificarse al interpretar un sensor?','["Calibración y condiciones de medición.","Solo el diseño exterior.","Su nombre comercial.","El color de la pantalla."]'::jsonb,0,'La calidad de la lectura depende de cómo y dónde se mide.'),
('investigacion_usuarios','Escuchar, observar y contrastar','La investigación con usuarios combina entrevistas, observación y pruebas para descubrir necesidades.','Usuarios pueden declarar que usan una opción, pero una prueba revela dificultades de navegación.','¿Qué método muestra problemas de uso reales?','["Observar tareas realizadas por usuarios.","Suponer preferencias del equipo.","Evitar pruebas.","Preguntar solo a quien desarrolló el producto."]'::jsonb,0,'La observación directa complementa los testimonios y descubre fricciones.'),
('aprendizaje_automatico','Modelos que aprenden de datos','El aprendizaje automático detecta patrones en ejemplos; desempeño, sesgos y generalización deben evaluarse.','Un modelo estima demanda de agua a partir de registros históricos, pero cambios de clima pueden alterar su precisión.','¿Qué NO garantiza entrenar un modelo con datos históricos?','["Acertar siempre en situaciones futuras.","Encontrar correlaciones.","Generar predicciones.","Evaluar datos de prueba."]'::jsonb,0,'Los patrones pueden cambiar y el conjunto de entrenamiento puede no representar el futuro.'),
('bioinformatica','Biología y programación juntas','La bioinformática usa métodos computacionales para estudiar secuencias, estructuras y datos biológicos.','Comparar miles de secuencias genéticas puede ayudar a investigar similitudes entre organismos.','¿Qué combinación caracteriza a la bioinformática?','["Biología y análisis computacional.","Biología sin datos.","Solo diseño gráfico.","Mecánica sin modelos."]'::jsonb,0,'La disciplina integra preguntas biológicas con algoritmos y estadística.'),
('gemelos_digitales','Representaciones conectadas al mundo físico','Un gemelo digital integra un modelo con información actualizada del sistema real para analizar su estado.','Un modelo de puente se alimenta de sensores para estudiar tendencias de deformación y escenarios de mantenimiento.','¿En qué se distingue de un modelo 3D estático?','["Integra datos del sistema físico a lo largo del tiempo.","Solo tiene más colores.","Debe ser una animación.","No requiere información externa."]'::jsonb,0,'La actualización con datos del sistema real es parte central del enfoque.'),
('robotica','Percibir, decidir y actuar','La robótica integra sensores, controladores y actuadores para interactuar con el mundo físico.','Un robot móvil mide distancia, decide una trayectoria y ajusta sus motores.','¿Qué componente permite actuar físicamente?','["Actuador.","Archivo PDF.","Lista de contactos.","Color del chasis."]'::jsonb,0,'El actuador convierte órdenes de control en movimiento u otra acción.'),
('ecosistemas','Interacciones en el ambiente','Un ecosistema involucra seres vivos y condiciones físicas conectadas por flujos de materia y energía.','La urbanización puede modificar infiltración del agua, hábitat y temperatura local.','¿Cuál ejemplo representa una interacción ecosistémica?','["Plantas, suelo y agua influyen entre sí.","Un objeto se estudia sin entorno.","Solo importa una especie aislada.","El clima no afecta a los seres vivos."]'::jsonb,0,'Los componentes bióticos y abióticos están conectados.'),
('gobernanza_ia','Supervisar IA con responsabilidad','Gobernar IA implica definir usos permitidos, responsabilidades, evaluación de sesgos y mecanismos de revisión.','Una herramienta para orientar estudiantes debe permitir correcciones y no tomar decisiones definitivas sin supervisión.','¿Qué medida mejora la gobernanza de una IA?','["Auditorías y revisión de decisiones relevantes.","Opacidad total.","Ausencia de responsables.","Impedir toda apelación."]'::jsonb,0,'La supervisión y la trazabilidad mejoran la rendición de cuentas.')
)
insert into public.concept_lessons(concept_id,lesson_stage,title,explanation,worked_example,exercise_question,exercise_options,correct_option,answer_explanation,editorial_status,source_status)
select c.id,'starter',i.title,i.explanation,i.worked_example,i.question,i.options,i.correct_option,i.feedback,'draft','original_draft'
from imported i join public.knowledge_concepts c on c.slug=i.slug
on conflict(concept_id,lesson_stage) do nothing;
